target.css:
:root {
  --card-bg: #ffffff;
  --header-bg: #2d5f3f;
  --accent: #f0a500;
  --text-primary: #1a1a2e;
  --text-secondary: #5a6472;
  --badge-bg: #d4edda;
  --badge-text: #1e7e34;
  --due-color: #c0392b;
  --footer-bg: #f7f9f7;
  --border-color: #dce5dc;
  --btn-bg: #2d5f3f;
  --btn-text: #ffffff;
  --divider-color: #dce5dc;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.checkout-card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 14px;
  width: 360px;
  overflow: hidden;
}

.card-header {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
}

.library-icon {
  font-size: 28px;
  line-height: 1;
}

.header-text {
  flex: 1;
}

.library-name {
  font-size: 11px;
  color: #a8c9b0;
  margin: 0 0 2px 0;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.card-title {
  font-size: 17px;
  font-weight: 700;
  color: #ffffff;
  margin: 0;
}

.status-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 600;
  padding: 3px 9px;
  border-radius: 20px;
}

.book-info {
  padding: 18px 16px 14px;
  border-bottom: 1px solid var(--border-color);
}

.book-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0 0 4px 0;
}

.book-author {
  font-size: 13px;
  color: var(--text-secondary);
  margin: 0;
}

.card-footer {
  background: var(--footer-bg);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
}

.date-block {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.date-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  font-weight: 600;
}

.date-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.date-value.due {
  color: var(--due-color);
}

.divider {
  width: 1px;
  height: 32px;
  background: var(--divider-color);
}

.renew-btn {
  margin-left: auto;
  background: var(--btn-bg);
  color: var(--btn-text);
  border: none;
  border-radius: 8px;
  padding: 8px 18px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

